// Regenerates src/pdfWorkerSource.ts from the installed pdfjs-dist build.
// Run after bumping pdfjs-dist: node scripts/embed-worker.js
const fs = require("fs");
const src = fs.readFileSync("node_modules/pdfjs-dist/build/pdf.worker.min.mjs", "utf8");
fs.writeFileSync(
    "src/pdfWorkerSource.ts",
    "// AUTO-GENERATED by scripts/embed-worker.js — pdf.js worker embedded so the
" +
        "// API and worker versions can never mismatch. Do not edit.
" +
        "export const PDF_WORKER_SOURCE: string = " + JSON.stringify(src) + ";
"
);
console.log("embedded", src.length, "bytes");
